on(release){
   this._visible = false;
   _parent.NMHBtn.enabled = true;
   _parent.ButtonNew.enabled = true;
   _parent.ButtonUp.enabled = true;
   _parent.ButtonDown.enabled = true;
   _parent.ButtonAns.enabled = true;
}

on(release){
   NMHBtn.enabled = false;
   Mc_Popup._visible = true;
   disableButton();
}

stop();
_global.rndAudio = new Array();
_global.rndAudio[0] = "S1";
_global.rndAudio[1] = "S2";
_global.rndAudio[2] = "S3";
_global.rndAudio[3] = "S4";
tempInt = random(_global.rndAudio.length);
tempLabel = _global.rndAudio[tempInt];
gotoAndPlay(tempLabel);

function enableButton()
{
   i = 1;
   while(i <= 9)
   {
      eval("Scr_" + i).enabled = true;
      i++;
   }
}
function disableButton()
{
   i = 1;
   while(i <= 9)
   {
      eval("Scr_" + i).enabled = false;
      i++;
   }
}
stop();
_global.quizSection = true;
_global.quizDragCount = 0;
WrongFeed._visible = false;
Mc_Popup._visible = false;

on(releaseOutside,release){
   stopDrag();
   tempSplSrc = this._name.split("_");
   if(eval(this._droptarget) == _parent["Mc_Tar_" + tempSplSrc[tempSplSrc.length - 1]])
   {
      _global.quizDragCount++;
      _parent["Mc_Tar_" + tempSplSrc[tempSplSrc.length - 1]]._alpha = 100;
      _parent.disableButton();
      _parent.NMHBtn.enabled = false;
      _parent.Coach_audio_2.gotoAndPlay(2);
      this._visible = false;
   }
   else
   {
      this._x = oX;
      this._y = oY;
      _parent.disableButton();
      _parent.NMHBtn.enabled = false;
